import { Layout, Card, Select, Space} from "antd";
import { Content } from "antd/es/layout/layout";
import React, { useState, useEffect } from "react";
const { Option } = Select;

const Home =() => {
    const [pokemonData, setPokemonData] = useState([]);
    const [pairsList, setPairsList] = useState([]);

    const [eventList, setEventList] = useState([])
    const [selectedOptionOne, setSelectedOptionOne] = useState('');
    const [selectedOptionTwo, setSelectedOptionTwo] = useState('');

    const [currentType, setcurrentType] = useState([])

    useEffect(() => {
        const fetchPokemonData = async () => {
            try {
                const response = await fetch('PoMaHSE/data/sync_pairs.json');
                const data = await response.json();
                setPokemonData(data);
                setPairsList(data)
            } catch (error) {
                console.error('读取拍组失败:', error);
            }
        };

        const fetchEventData = async () => {
            try {
                const response = await fetch('PoMaHSE/data/events.json');
                const data = await response.json()
                setEventList(data)
            } catch (error) {
                console.error('读取活动失败:', error)
            }
        }

        fetchPokemonData();
        fetchEventData();
    }, []);
    
    // console.log(pokemonData)
    
    useEffect(() => {
        setPairsList(pokemonData.filter(item => (item[selectedOptionOne] === true || selectedOptionOne === '') 
            && (item['Label'].some(i => i === selectedOptionTwo) || selectedOptionTwo === '')))
    }, [selectedOptionOne, selectedOptionTwo])

    const EventClick = (id) => {
        setcurrentType(eventList.find(item => item.id === id).Type)
    }

    useEffect(() => {
        setSelectedOptionOne('')
        setSelectedOptionTwo('')
    }, [currentType])
    
    return (
        <Layout>
            <Content className="homepage" 
                style={{ 
                    background: `url(${process.env.PUBLIC_URL}/background.png) repeat`,
                    backgroundSize: 'auto', 
                    backgroundPosition: 'center',
                    height: '90vh',
                    width: '100vw',
                    margin: '0px',
                    position: 'relative'
                }}
            > 
                <Space direction="vertical" size={4} style={{ 
                    position: 'absolute',
                    left: '5%',
                    zIndex: 10
                }}>
                    <Select
                        value={selectedOptionOne}
                        onChange={setSelectedOptionOne}
                        placeholder="选择 A, B 或 C"
                        style={{ width: '10vw', marginTop: '8px', left: "5%"}}
                        >
                        <Option value="Confusion">Confusion</Option>
                        <Option value="Trap">Trap</Option>
                        <Option value="Flitch">Flitch</Option>
                    </Select>
                    <Select
                        value={selectedOptionTwo}
                        onChange={setSelectedOptionTwo}
                        placeholder="选择 A, B 或 C"
                        style={{ width: '10vw', marginTop: '8px', left: "5%"}}
                        >
                        <Option value="Main Character">Main Character</Option>
                        <Option value="Champion">Champion</Option>
                        <Option value="Rival">Rival</Option>
                    </Select>
                </Space>
                
                <ul className="event-list"
                    style={{
                        marginTop: "7%",
                        width: '20%',
                        height: '80%',
                        overflowY: 'auto',           
                        overflowX: 'hidden',         
                        scrollbarWidth: 'thin',      
                        scrollbarColor: '#c0c0c0 transparent', 

                        WebkitOverflowScrolling: 'touch'
                    }}
                >
                    {
                        eventList.map(item => {
                            return (
                                <li style={{
                                    overflow: "hidden",
                                    cursor: 'pointer'
                                    }}
                                    onClick={() => EventClick(item.id)}                                   
                                >
                                    <img src={item.Icon} alt="eventIcon"
                                        style = {{
                                            width: '100%',
                                            height: 'auto',
                                            objectFit: 'cover',
                                            display: 'block',
                                            margin: '5px'
                                        }}
                                    ></img>
                                </li>
                            )
                        })
                    }
                </ul>
                <div className="container-box"
                    style = {{
                        width: '75%',
                        height: '90%',
                        boxSizing: 'border-box',
                        backgroundColor: 'rgba(58, 169, 255, 0.3)',
                        position: 'absolute',
                        right: '2vw',
                        bottom: '1vh',
                        borderRadius: '30px'
                    }}>
                    <div style={{
                        display: 'grid',
                        gridTemplateColumns: 'repeat(8, 1fr)',  // 8列
                        gridTemplateRows: 'repeat(5, 100px)',   // 5行，每行100px
                        gap: '0.1vw',
                        padding: '2%'
                    }}>
                        {
                            pairsList.map(item => {
                                return ( 
                                <div
                                    key={item.id}
                                    style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        boxSizing: 'border-box'
                                    }}
                                    
                                    >
                                        <img src={item.Icon} alt='icon' style={{
                                            width: '100%',    
                                            height: '100%',
                                            objectFit: 'contain', 
                                        }}></img>
                                </div>)
                            })
                        }
                    </div>
                </div>
                
                
                
            </Content>
        </Layout>
        
        
    )
}

export default Home;